pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address a, address b, uint256 id, bytes calldata data) public {
        vm.assume(a != address(0));
        vm.assume(b != address(0));
        bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
        bytes4 returned = c.onERC721Received(a, b, id, data);
        assertTrue(returned == expected);
    }
}
